import numpy as np
from scipy.stats import norm

def gelu_exact(x):
    return x * norm.cdf(x)  # multiplies input by the probability a standard normal variable is less than it

def gelu_approx(x):
    return 0.5 * x * (1 + np.tanh(np.sqrt(2 / np.pi) * (x + 0.044715 * x**3)))  # the common, fast approximation

def relu(x):
    return np.maximum(0, x)

test_inputs = np.array([-2.0, -0.5, -0.1, 0.0, 0.5, 2.0])

print("Input | ReLU | GELU (exact) | GELU (approx)")
for x in test_inputs:
    print(f"  {x:5.2f} | {relu(x):5.2f} |   {gelu_exact(x):8.5f}   |   {gelu_approx(x):8.5f}")

print("\nNotice GELU (exact) dips very slightly negative around x=-0.1 to -0.5,")
print("the non-monotonic property covered in this topic, unlike ReLU which is always exactly 0 or the input")
